contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will perform Deposit (by sending ether) then attempt Collect(_am).
    // Parameters:
    // - depositAmt: amount to deposit into c from this contract
    // - collectAmt: amount to request via Collect
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient balance to deposit");

        // initial observations
        uint beforeBalanceRecorded = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // make a deposit to C: this uses the receive -> Deposit path
        if (depositAmt > 0) {
            c.deposit{value: depositAmt}();
        }

        // observe after deposit
        uint afterDepositRecorded = c.balances(address(this));
        uint afterDepositContractEth = address(c).balance;

        // The deposit must have increased the recorded balance by exactly depositAmt
        // This is a sanity check observation but not the final assert; keep as require so proof obligations assume it.
        require(afterDepositRecorded == beforeBalanceRecorded + depositAmt, "deposit should increase recorded balance");
        require(afterDepositContractEth == beforeContractEth + depositAmt, "contract ETH should increase by depositAmt");

        // Attempt Collect and catch revert flag
        bool reverted;
        try c.Collect(collectAmt) { reverted = false; } catch { reverted = true; }

        // observe after collect attempt
        uint afterRecorded = c.balances(address(this));
        uint afterContractEth = address(c).balance;

        // General property to assert:
        // If Collect succeeded (not reverted) then:
        //  - before recorded balance (afterDepositRecorded) must have been >= MinSum and >= collectAmt (otherwise Collect would not run the transfer branch)
        //  - recorded balance decreased by exactly collectAmt
        //  - contract ETH decreased by at least collectAmt
        // If Collect reverted then neither recorded balance nor contract ETH decreased.
        uint minSum = c.MinSum();

        assert(
            // case: Collect reverted
            (reverted && afterRecorded == afterDepositRecorded && afterContractEth == afterDepositContractEth)
            ||
            // case: Collect did not revert
            (!reverted
             && afterDepositRecorded >= minSum
             && afterDepositRecorded >= collectAmt
             && afterRecorded + collectAmt == afterDepositRecorded
             && afterContractEth + collectAmt <= afterDepositContractEth)
        );
    }

    // allow receiving refunds if Collect forwards Ether
    receive() external payable {}
}

