        // Observe after collect attempt
        uint afterRecorded = c.balances(address(this));
        uint afterEth = address(c).balance;

        uint minSum = c.MinSum();

        // Exactly one assert expressing the general rule:
        // - If Collect reverted: balances and ETH unchanged from after deposit.
        // - If Collect succeeded: the recorded balance decreased exactly by collectAmt,
        //   and the contract ETH decreased by at least collectAmt, and the pre-collect recorded balance
