        assert(
            (reverted && afterRecorded == afterDepositRecorded && afterEth == afterDepositEth)
            ||
            (!reverted
             && afterDepositRecorded >= minSum
             && afterDepositRecorded >= collectAmt
             && afterRecorded + collectAmt == afterDepositRecorded
             && afterEth + collectAmt <= afterDepositEth)
