contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to Collect _am after ensuring MinSum is set and the test has a deposited balance
    function run(uint initialDeposit, uint MinSum, uint _am) public payable {
        require(address(this).balance >= initialDeposit, "need funds to deposit");
        // initial setup: set MinSum and log then mark initialized
        c.SetMinSum(MinSum);
        c.SetLogFile(address(c));
        c.Initialized();

        // Deposit initialDeposit into c from this contract
        c.Deposit{value: initialDeposit}();

        // read balance before collect (public getter)
        uint beforeBal = c.balances(address(this));
        uint beforeThisBal = address(this).balance;

        // attempt Collect and record whether it reverted
        bool didRevert;
        try c.Collect(_am) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint afterBal = c.balances(address(this));
        uint afterThisBal = address(this).balance;

        // If Collect did not revert, then the recorded balance must have decreased by exactly _am
        // and this contract's ETH balance must have increased by exactly _am.
        // Also require that beforeBal was >= MinSum and >= _am as precondition for successful Collect.
        if (!didRevert) {
            // these are the expected relations when Collect succeeded
            assert(beforeBal >= MinSum && beforeBal >= _am && afterBal + _am == beforeBal && afterThisBal == beforeThisBal + _am);
        } else {
            // If it reverted, we assert that at least one of the success preconditions was false.
            assert(!(beforeBal >= MinSum && beforeBal >= _am) || afterBal == beforeBal);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint initialDeposit, uint MinSum, uint _am) public payable {
        require(address(this).balance >= initialDeposit, "need funds to deposit");

        // initialize C: set MinSum and Log, then mark initialized
        c.SetMinSum(MinSum);
        c.SetLogFile(address(c));
        c.Initialized();

        // deposit funds into C from this contract
        c.Deposit{value: initialDeposit}();

        // read before values
        uint beforeBal = c.balances(address(this));
        uint beforeThisBal = address(this).balance;

        // attempt Collect and capture whether it reverted by comparing post-state
        // perform the call; if it reverts, state won't change and this call will revert the whole run,
        // so we instead call Collect via low-level call to detect success without reverting this transaction
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));

        // read after values
        uint afterBal = c.balances(address(this));
        uint afterThisBal = address(this).balance;

        // General invariant expressed as a single assert:
        // If Collect succeeded then recorded balance decreased by _am and this contract's balance increased by _am.
        // If Collect failed then at least one required condition for success was false: beforeBal < MinSum or beforeBal < _am,
        // and in that case recorded balance must be unchanged.
        assert(
            (success && afterBal + _am == beforeBal && afterThisBal == beforeThisBal + _am)
            || (!success && (afterBal == beforeBal) && (beforeBal < MinSum || beforeBal < _am))
        );
    }

    receive() external payable {}
}

