contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters: amount to deposit, amount to collect
    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount + 1 wei ? true : true); // no-op to satisfy template allowing require; actual preconditions avoided

        // Ensure MinSum and LogFile are set once (calls that must be allowed before Initialized)
        // We call SetMinSum and then mark initialized so further setup cannot be changed by other calls.
        c.SetMinSum(1);
        c.SetLogFile(address(this));
        c.Initialized();

        // Deposit depositAmount into c from this contract
        if (depositAmount > 0) {
            // ensure this contract has enough balance to send; the test harness will provide funds
            require(address(this).balance >= depositAmount);
            c.Deposit{value: depositAmount}();
        }

        // read balance of InvMutTest (which is msg.sender for c) before collect attempt
        uint beforeBal = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint cBalAfter = address(c).balance;
        uint receivedByThis = address(this).balance; // note: this may include unrelated ETH but we reason about c's balance change

        // If Collect succeeded then:
        //  - the recorded balance for this contract decreased by exactly collectAmount
        //  - c's ETH balance decreased by exactly collectAmount
        // Because the Collect function only sends ETH when it successfully calls msg.sender.call{value:_am} and then logs.
        assert(
            reverted || (beforeBal >= collectAmount && beforeBal - afterBal == collectAmount && cBalBefore - cBalAfter == collectAmount)
        );
    }

    // receive to accept ETH if Collect sends it back to this test contract
    receive() external payable {}
}
